KG42.register("rules-d1a656d4a996636ad49aa9d8",{"id":"39-dynamic_congestion_tariff::v141-c-R003","paper":"39-dynamic_congestion_tariff","record":{"rule_id":"v141-c-R003","mechanism_id":"v141-a-M02","name":"Price-signal coordination","process_stage":"coordination","market_meaning":"Tentative demand-response submissions provide the information used to identify congestion and modify DPT coordination signals accordingly. Scope: Iterative DPT congestion-management planning between aggregators and the DSO. DPT coordination determines a rate for each load bus and time period according to network conditions and forecast nonflexible load, with the objective that aggregator energy schedules respect network limits. Scope: DPT rate determination for distribution-network congestion-management planning. The tentative DPT signals are initialized to zero. Scope: Initialization of the iterative DPT coordination procedure. Condition: At initiation of the iterative process. The DPT coordination process continues iterating until network constraints are satisfied and final DPT rates are determined. Scope: Continuation and termination of iterative DPT coordination. The line-flow and voltage marginal-price signals are constrained to be nonnegative before transformation into DPTs. Scope: Internal signal restrictions in iterative DPT calculation. The final DPT rates equal the last iteration DPT rates. Scope: Finalization of iterative DPT signals. Condition: When the DPT iteration converges.","independence_rationale":"Relations governed by the approved function coordination.price_signal under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["bidding.demand","coordination.price_signal"],"E":[{"edge_id":"v141-c-R003-E001","source":"bidding.demand","target":"coordination.price_signal","type":"links","constraint_ids":["v141-c-R003-C001"],"evidence_ids":["v141-b-g13-E13"]}],"omega":{"market_type":"DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"coordination","context_text":"Continuation and termination of iterative DPT coordination. | DPT rate determination for distribution-network congestion-management planning. | Finalization of iterative DPT signals. | Initialization of the iterative DPT coordination procedure. | Internal signal restrictions in iterative DPT calculation. | Iterative DPT congestion-management planning between aggregators and the DSO.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g02-e013","v141-b-g02-e016","v141-b-g12-E12","v141-b-g13-E13"]},"x":[{"variable_id":"v141-c-R003-X001","symbol":"\\lambda_t","meaning":"Line-flow marginal-price signal vector used and updated in the iterative DPT coordination loop.","kind":"operational","domain":"\\mathbb{R}^{N_L}","unit":null,"indices":["t∈N_T","iteration k"],"evidence_ids":["v141-b-g04-E04","v141-b-g02-e011"]},{"variable_id":"v141-c-R003-X002","symbol":"\\omega_t","meaning":"Voltage marginal-price signal vector used and updated in the iterative DPT coordination loop.","kind":"operational","domain":"\\mathbb{R}^{N_d}","unit":null,"indices":["t∈N_T","iteration k"],"evidence_ids":["v141-b-g04-E04","v141-b-g02-e011"]},{"variable_id":"v141-c-R003-X003","symbol":"R_t","meaning":"Matrix form of the DPT rates determined iteratively by the DSO at each coordination iteration.","kind":"operational","domain":"\\mathbb{R}^{N_d\\times N_d}","unit":null,"indices":["t∈N_T","iteration k"],"evidence_ids":["v141-b-g04-E04","v141-b-g02-e011","v141-b-g16-E16"]},{"variable_id":"v141-c-R003-X004","symbol":"s_t","meaning":"Total apparent power load at each load point, determined from aggregator demand responses and conventional load in the DPT iteration.","kind":"operational","domain":"\\mathbb{C}^{N_d}","unit":null,"indices":["t∈N_T","iteration k"],"evidence_ids":["v141-b-g02-E02","v141-b-g02-e009","v141-b-g02-e011"]}],"theta":[{"parameter_id":"v141-c-R003-P001","symbol":"\\alpha","meaning":"Step size used in the DPT signal update equations.","value":{"kind":"symbolic","number_value":null,"text_value":"proper step size"},"unit":null,"indices":[],"evidence_ids":["v141-b-g03-E03","v141-b-g02-e011"]},{"parameter_id":"v141-c-R003-P002","symbol":"\\tau","meaning":"Small tolerance used in the convergence checks for lambda, omega, and DPT rates.","value":{"kind":"symbolic","number_value":null,"text_value":"small tolerance"},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-e013"]},{"parameter_id":"v141-c-R003-P003","symbol":"D","meaning":"Power transfer distribution factor (PTDF) matrix used in line-flow checks and in the DPT transformation.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-E02","v141-b-g02-e011"]},{"parameter_id":"v141-c-R003-P004","symbol":"F_t","meaning":"Line loading limit of active power used in the line-flow residual of the DPT update.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["t∈N_T"],"evidence_ids":["v141-b-g02-E02","v141-b-g02-e007","v141-b-g02-e011"]},{"parameter_id":"v141-c-R003-P005","symbol":"Z","meaning":"Inverse matrix of the partial nodal admittance matrix Y_{LL}, used in the voltage residual and voltage-signal transformation.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g03-E03","v141-b-g02-e018","v141-b-g02-e011"]},{"parameter_id":"v141-c-R003-P006","symbol":"V_0","meaning":"Voltage at node 0 used in the voltage residual and voltage-signal transformation.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g03-E03","v141-b-g02-e011"]},{"parameter_id":"v141-c-R003-P007","symbol":"\\underline V","meaning":"Lower voltage limit used in the voltage residual of the DPT update.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":[],"evidence_ids":["v141-b-g02-E02","v141-b-g02-e011"]}],"phi":[{"constraint_id":"v141-c-R003-C001","kind":"procedural","role":"core","statement":"Tentative demand-response submissions provide the information used to identify congestion and modify DPT coordination signals accordingly. Scope: Iterative DPT congestion-management planning between aggregators and the DSO.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["bidding.demand","coordination.price_signal"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g13-E13"]},{"constraint_id":"v141-c-R003-C002","kind":"procedural","role":"core","statement":"DPT coordination determines a rate for each load bus and time period according to network conditions and forecast nonflexible load, with the objective that aggregator energy schedules respect network limits. Scope: DPT rate determination for distribution-network congestion-management planning.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["coordination.price_signal"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g12-E12"]},{"constraint_id":"v141-c-R003-C003","kind":"mathematical","role":"core","statement":"The tentative DPT signals are initialized to zero. Scope: Initialization of the iterative DPT coordination procedure. Condition: At initiation of the iterative process.","expression":"\\lambda_t^{(1)}=0,\\quad \\omega_t^{(1)}=0,\\quad R_t^{(1)}=0,\\quad \\forall t\\in N_T","formalization_origin":"source","template_id":null,"members":["coordination.price_signal"],"variable_refs":["v141-c-R003-X001","v141-c-R003-X002","v141-c-R003-X003"],"parameter_refs":[],"evidence_ids":["v141-b-g13-E13","v141-b-g02-e010"]},{"constraint_id":"v141-c-R003-C004","kind":"mathematical","role":"core","statement":"The DPT coordination process continues iterating until network constraints are satisfied and final DPT rates are determined. Scope: Continuation and termination of iterative DPT coordination.","expression":"D\\operatorname{Re}(s_t^{(k)})-F_t\\le 0,\\quad -1+\\frac{1}{V_0^2}\\operatorname{Re}(Zs_t^{(k)})+\\frac{\\underline V}{V_0}\\le 0,\\quad |\\lambda_t^{(k+1)}-\\lambda_t^{(k)}|\\le\\tau,\\quad |\\omega_t^{(k+1)}-\\omega_t^{(k)}|\\le\\tau,\\quad |R_t^{(k+1)}-R_t^{(k)}|\\le\\tau,\\quad \\forall t\\in N_T","formalization_origin":"source","template_id":null,"members":["coordination.price_signal"],"variable_refs":["v141-c-R003-X001","v141-c-R003-X002","v141-c-R003-X003","v141-c-R003-X004"],"parameter_refs":["v141-c-R003-P002","v141-c-R003-P003","v141-c-R003-P004","v141-c-R003-P005","v141-c-R003-P006","v141-c-R003-P007"],"evidence_ids":["v141-b-g13-E13","v141-b-g02-e013","v141-b-g02-e011"]},{"constraint_id":"v141-c-R003-C005","kind":"mathematical","role":"core","statement":"The line-flow and voltage marginal-price signals are constrained to be nonnegative before transformation into DPTs. Scope: Internal signal restrictions in iterative DPT calculation.","expression":"\\lambda_t=(\\lambda_t)^+,\\quad \\omega_t=(\\omega_t)^+,\\quad \\forall t\\in N_T","formalization_origin":"source","template_id":null,"members":["coordination.price_signal"],"variable_refs":["v141-c-R003-X001","v141-c-R003-X002"],"parameter_refs":[],"evidence_ids":["v141-b-g02-e016","v141-b-g02-e012"]},{"constraint_id":"v141-c-R003-C006","kind":"mathematical","role":"core","statement":"The final DPT rates equal the last iteration DPT rates. Scope: Finalization of iterative DPT signals. Condition: When the DPT iteration converges.","expression":"R_t^{\\mathrm{final}}=R_t^{(K)},\\quad \\forall t\\in N_T,\\quad K\\text{ denotes the last iteration}","formalization_origin":"source","template_id":null,"members":["coordination.price_signal"],"variable_refs":["v141-c-R003-X003"],"parameter_refs":[],"evidence_ids":["v141-b-g02-e013"]},{"constraint_id":"v141-c-R003-C007","kind":"mathematical","role":"core","statement":"During DPT coordination, the line-flow marginal-price signal, voltage marginal-price signal, and DPT-rate matrix are updated from the network residuals using the step size and the DPT transformation matrices, for every time period.","expression":"\\lambda_t^{(k+1)}=\\lambda_t^{(k)}+\\alpha\\left(D\\operatorname{Re}(s_t^{(k)})-F_t\\right),\\quad \\omega_t^{(k+1)}=\\omega_t^{(k)}+\\alpha\\left(-1+\\frac{1}{V_0^2}\\operatorname{Re}(Zs_t^{(k)})+\\frac{\\underline V}{V_0}\\right),\\quad R_t^{(k+1)}=D^T\\lambda_t^{(k+1)}+\\frac{\\operatorname{Re}(Z^T)}{V_0^2}\\omega_t^{(k+1)},\\quad \\forall t\\in N_T","formalization_origin":"source","template_id":null,"members":["bidding.demand","coordination.price_signal"],"variable_refs":["v141-c-R003-X001","v141-c-R003-X002","v141-c-R003-X003","v141-c-R003-X004"],"parameter_refs":["v141-c-R003-P001","v141-c-R003-P003","v141-c-R003-P004","v141-c-R003-P005","v141-c-R003-P006","v141-c-R003-P007"],"evidence_ids":["v141-b-g02-e011","v141-b-g02-e016"]}],"pi":[{"evidence_id":"v141-b-g02-e013","location":{"location_id":"src-c263a83472-p05-c1r3__v141-a-M02-validation","page":5,"printed_page":null,"section":"III-A. Mathematical Formulation of DPT Method","anchor_text":"pr λt = (λt)+, (14) co ωt = (ωt)+, (15) are i.e., if they are negative, they will be replaced with z","equation_id":"(14)-(15)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"When the iteration converges, the residuals in (11) and (12) will be nonpositive, which means constraints (7) and (8) are satisfied. There are |\\lambda_t^{(k+1)}-\\lambda_t^{(k)}|\\le\\tau, |\\omega_t^{(k+1)}-\\omega_t^{(k)}|\\le\\tau and |R_t^{(k+1)}-R_t^{(k)}|\\le\\tau, where \\lambda_t and \\omega_t are modified values using (14) and (15), and \\tau is a small tolerance. The final DPT rates are the same as the last iteration DPT rates (Fig. 2)."},{"evidence_id":"v141-b-g02-e016","location":{"location_id":"src-c263a83472-p05-c2r3__v141-a-M02-coordination","page":5,"printed_page":null,"section":"III-B. Control Diagram of the Iteration Process","anchor_text":"proﬁles. Then, the power ﬂows are sent to the power ﬂow 4) controller (upper part of the diagram), a","equation_id":null,"figure_id":"Fig. 3","table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"definition"},"source_text":"After gathering the planning results from the aggregators, the DSO performs load flow analysis and determines the network status, including line flows and voltage profiles. Then, the power flows are sent to the power flow controller (upper part of the diagram), and the voltage profiles are sent to the voltage controller (lower part of the diagram). The received signals (flows and voltages) are compared with the references respectively, and then the error signals are multiplied by the step size \\alpha. Then the signals enter two integrators, which are corresponding to (11) and (12), respectively. Afterwards, two limiters force the signals to be nonnegative, which are corresponding to (14) and (15), respectively. Then the signals (marginal prices for line flow and voltage respectively) are transformed to DPTs by the matrix D^T and matrix \\operatorname{Re}(Z^T)/V_0^2, respectively."},{"evidence_id":"v141-b-g12-E12","location":{"location_id":"src-c263a83472-p03-c2r3__v141-a-M02-pricing","page":3,"printed_page":null,"section":"II-B. Congestion Management Through Power Tariff","anchor_text":"gy p gg gators, who represent the owners of the ﬂexible demands, need t. to buy electricity from an ","equation_id":null,"figure_id":"Fig. 2","table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"2) Implementation Scenario Two (DPT): In this scenario, power tariff has a dynamic rate (varying with location and time period), i.e., DPT. This scenario is the focus of the rest of the paper. DPT can replace DT completely in congestion management of distribution networks, as it creates the same incentives as the DT method does for the customers/aggregators to reschedule their energy planning and avoid/alleviate potential congestion during planning stage. DPT does not contain energy prices. Therefore, the aggregators, who represent the owners of the flexible demands, need to buy electricity from an electricity (energy) market, such as the day-ahead spot market in Nordic (Nord pool) or the day-ahead market of the California ISO in USA. An important task in the implementation of the DPT method for congestion management is to determine a proper DPT rate for each node (load bus) and each time period according to the network conditions and forecasted nonflexible load level, so that the energy schedules of the aggregators respect the network limits. As the DPT method works together with the day-ahead spot market, the time periods for the DPT rates are typically 24 hourly based periods of the next day, i.e., in line with the day-ahead market. With the DT method, the DT rates are determined by the DSO through a centralized optimization. Unlike the DT method, DPT rates are determined by iterative interactions between the DSO and aggregators."},{"evidence_id":"v141-b-g13-E13","location":{"location_id":"src-c263a83472-p03-c2r4__v141-a-M02-coordination","page":3,"printed_page":null,"section":"II-B. Congestion Management Through Power Tariff","anchor_text":"ers of implementing the DPT method for congestion manage- der ment is illustrated in Fig. 2. Step 1,","equation_id":null,"figure_id":"Fig. 2","table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"Step 1, the DSO initiates the iterative process by sending out tentative DPTs (= 0). Step 2, the aggregators will separately make their own optimal purchasing plans by minimizing the energy cost and the network tariff cost. Step 3, the aggregators will send back the tentative demand responses (DRs) to the DSO. Step 4, with the new information, the DSO will be able to identify the congestion points (if any) and modify the DPT rates according to the identified congestion. Step 5, the DSO sends out the new DPTs to the aggregator and the iterative process continues (go back to Step 2) till the network constraints are satisfied and the final DPT rates are determined. As in many other congestion management methods, Step 4 is to identify the congestion risk and allocate the risk to the responsible party through the DPT calculation (the DPT is also a locational price). Step 2 is to optimize the energy consumption plan by each aggregator taking into account the congestion risk reflected in the DPT. Steps 2∼5 form an iterative process to finally reach an optimal planning with respect to the network constraints."},{"evidence_id":"v141-b-g02-E02","location":{"location_id":"src-c263a83472-p01-c1r3__v141-a-M02-clearing","page":1,"printed_page":null,"section":"Nomenclature","anchor_text":"( ), e ect c ve c e ( V), eat pu p ( ). Va NOMENCLATURE Parameters Ai,t,t_ coefﬁcient matrix, descri","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"Parameters: \\(A_{i,t,t'}\\) coefficient matrix, describe the relations between the power consumption and temperature change of the household; \\(D\\) power transfer distribution factor (PTDF); \\(\\tilde E_{i,t}, E_i\\) customer to load bus mapping matrix; \\(F_t\\) line loading limit of active power; \\(K_{i,t}^{a,min}\\) lower temperature limit; \\(K_{i,t}^{a,max}\\) upper temperature limit; \\(N_B\\) set of aggregators; \\(N_T\\) set of planning periods; \\(N_L\\) set of lines; \\(N_d\\) set of demand bus; \\(\\underline V\\) voltage lower limit."},{"evidence_id":"v141-b-g02-e007","location":{"location_id":"src-c263a83472-p04-c2r3__v141-a-M02-clearing","page":4,"printed_page":null,"section":"III-A.2) Formulation at the DSO Side","anchor_text":"ent pai,t = Ei pi,t + ˆpi,t , ∀t ∈Nt (6) he 2) Formulation at the DSO Side: At the DSO side, there i","equation_id":"(6)-(10)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"The inequalities of (7) and (8) are to compare the power flow and voltage level with the network limits, respectively.\nD\\operatorname{Re}(s_t)\\le F_t, \\forall t\\in N_T, (\\lambda_t) \\quad (7)\n1-\\frac{1}{V_0^2}\\operatorname{Re}(Zs_t)\\ge \\frac{V}{V_0}, \\forall t\\in N_T, (\\omega_t) \\quad (8)"},{"evidence_id":"v141-b-g02-e009","location":{"location_id":"src-c263a83472-p04-c2r3__v141-a-M02-clearing","page":4,"printed_page":null,"section":"III-A.2) Formulation at the DSO Side","anchor_text":"ent pai,t = Ei pi,t + ˆpi,t , ∀t ∈Nt (6) he 2) Formulation at the DSO Side: At the DSO side, there i","equation_id":"(6)-(10)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"After receiving the DR results, p^a_{i,t}, from all of the aggregators, the DSO will firstly determine the total apparent power load, s_t, for each bus using (9) and (10).\n\\operatorname{Re}(s_t)=p_t^c+\\sum_{i\\in N_B}p_{i,t}^a,\\forall t\\in N_T,(\\rho_t) \\quad (9)\n\\operatorname{Im}(s_t)=q_t^c,\\forall t\\in N_T \\quad (10)"},{"evidence_id":"v141-b-g02-e010","location":{"location_id":"src-c263a83472-p05-c1r1__v141-a-M02-pricing","page":5,"printed_page":null,"section":"III-A. Mathematical Formulation of DPT Method","anchor_text":"2152 otherwise, it will be zero. Even though the DSO does not need to model an optimization problem,","equation_id":"(11)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"Vectors \\lambda_t and \\omega_t play an important role in determining proper DPT rates, i.e., R_t. They are determined iteratively. Initially, they are zero, i.e., \\lambda_t^{(1)}=0, \\omega_t^{(1)}=0 and R_t^{(1)}=0. Then after receiving DR results p_{i,t}^{a(k)} from the aggregators (k refers to the k-th iteration, and p_{i,t}^{a(k)} is the optimal solution based on the k-th DPT, i.e., R_t^{(k)}), s_t^{(k)} can be determined."},{"evidence_id":"v141-b-g02-e011","location":{"location_id":"src-c263a83472-p05-c1r2__v141-a-M02-pricing","page":5,"printed_page":null,"section":"III-A. Mathematical Formulation of DPT Method","anchor_text":"t ) t Then, λt, ωt and Rt can be updated by, λ(k+1)t = λ(k)t + α DRe s(k)t −Ft , ∀t ∈NT, (11) 1 V ω(","equation_id":"(11)-(15)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"formula"},"source_text":"Then, \\lambda_t, \\omega_t and R_t can be updated by,\n\\lambda_t^{(k+1)}=\\lambda_t^{(k)}+\\alpha(D\\operatorname{Re}(s_t^{(k)})-F_t),\\ \\forall t\\in N_T, \\quad (11)\n\\omega_t^{(k+1)}=\\omega_t^{(k)}+\\alpha\\left(-1+\\frac{1}{V_0^2}\\operatorname{Re}(Zs_t^{(k)})+\\frac{V}{V_0}\\right),\\ \\forall t\\in N_T, \\quad (12)\nR_t^{(k+1)}=D^T\\lambda_t^{(k+1)}+\\frac{\\operatorname{Re}(Z^T)}{V_0^2}\\omega_t^{(k+1)},\\ \\forall t\\in N_T. \\quad (13)\nIn (11) and (12), \\alpha represents a proper step size, and the term after \\alpha is the residual of constraints (7) and (8), respectively. The justification of (11)-(13) will be discussed in Section III-B by a metaphor based on the control theory. There is an implicit requirement for the marginal prices \\lambda_t and \\omega_t, i.e., they must be nonnegative; therefore, they are modified by,"},{"evidence_id":"v141-b-g02-e012","location":{"location_id":"src-c263a83472-p05-c1r3__v141-a-M02-validation","page":5,"printed_page":null,"section":"III-A. Mathematical Formulation of DPT Method","anchor_text":"pr λt = (λt)+, (14) co ωt = (ωt)+, (15) are i.e., if they are negative, they will be replaced with z","equation_id":"(14)-(15)","figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"There is an implicit requirement for the marginal prices \\lambda_t and \\omega_t, i.e., they must be nonnegative; therefore, they are modified by,\n\\lambda_t=(\\lambda_t)^+, \\quad (14)\n\\omega_t=(\\omega_t)^+, \\quad (15)\ni.e., if they are negative, they will be replaced with zero."},{"evidence_id":"v141-b-g02-e018","location":{"location_id":"src-c263a83472-p04-c2r4__v141-a-M02-clearing","page":4,"printed_page":null,"section":"III-A.2) Formulation at the DSO Side","anchor_text":"mal Re (st) = pct + pai,t,∀t ∈NT, (ρt) (9) ast i∈NB Vs Im(st) = qct , ∀t ∈NT (10) her ed The Matrix ","equation_id":"(9)-(10)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"The Matrix Z is the inverse matrix of the partial nodal admittance matrix Y_{LL}, which is a submatrix of the full admittance matrix (Y_{00} represents the slack bus),\nY = [Y_{00} Y_{0L}; Y_{L0} Y_{LL}]."},{"evidence_id":"v141-b-g03-E03","location":{"location_id":"src-c263a83472-p01-c2r2__v141-a-M02-clearing","page":1,"printed_page":null,"section":"Nomenclature","anchor_text":"T), V0 voltage at node 0 on YLL the matrix obtained by removing the ﬁrst row and eat column of the n","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"\\(V_0\\) voltage at node 0; \\(Y_{LL}\\) the matrix obtained by removing the first row and column of the nodal admittance matrix; \\(Z\\) the inverse matrix of \\(Y_{LL}\\); \\(c_t\\) forecast baseline energy price; \\(d_{i,t}\\) discharging power of EVs due to driving; \\(e_i^{min}\\) lower limit of the state of charge (SOC) level; \\(e_i^{max}\\) upper limit of the SOC level; \\(e_{i,0}\\) initial SOC level; \\(p_{i,t}^{min}, p_{i,t}^{max}\\) lower/upper charging power limit of EVs; \\(\\hat p_i^{min}, \\hat p_i^{max}\\) lower/upper power limit of HPs; \\(p_t^c\\) active conventional power at each load point; \\(q_t^c\\) reactive conventional power at each load point; \\(u_{i,t}\\in R^{m_i}\\) initial temperature; \\(\\alpha\\) coefficient, step size; \\(\\beta_1\\) coefficient for reconditioning of voltage control."},{"evidence_id":"v141-b-g04-E04","location":{"location_id":"src-c263a83472-p01-c2r3__v141-a-M02-pricing","page":1,"printed_page":null,"section":"Nomenclature","anchor_text":"Variables pev, php, pc power level of EV, HP and conventional loads of a household/customer en pi, p","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-01.png","occurrence_role":"definition"},"source_text":"Variables: \\(p^{ev}, p^{hp}, p^c\\) power level of EV, HP and conventional loads of a household/customer; \\(p_i, p_{i,t}\\) charging power of EVs of one aggregator; \\(\\hat p_i, \\hat p_{i,t}\\) power consumption of HPs of one aggregator; \\(r, r_t\\) energy-based regulation price, i.e., DT rates; \\(r^p, r_t^p\\) power-based regulation price, i.e., DPT rates; \\(R\\) matrix form of the DPT rates; \\(s_t\\) total apparent power at each load point; \\(\\lambda_t\\) Lagrange multiplier (LM) of line limit constraint; \\(\\rho_t\\) LM of load equation; \\(\\omega_t\\) LM of voltage constraint."},{"evidence_id":"v141-b-g16-E16","location":{"location_id":"src-c263a83472-p04-c1r4__v141-a-M02-pricing","page":4,"printed_page":null,"section":"III-A.1) Formulation at the Aggregator Side","anchor_text":"will not be considered since it does not change the optimal energy schedule decisions (or can be mer","equation_id":"(1)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"definition"},"source_text":"An aggregator can use a quadratic function to represent the total cost including energy consumption and network tariff as shown in (1). The quadratic term in (1) is due to the DPT received from the DSO (\\(R_t\\) is the DPT; therefore, it is a fixed parameter for the optimizations at the aggregator side). Unlike the DT method, which requires price sensitivity coefficients by forecasting in order to have a quadratic programming formulation [4], the DPT method can have a quadratic programming formulation by the power tariff concept."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M02-coordination","v141-a-M02-participation","v141-a-M02-pricing","v141-a-M02-validation"],"extras":{"decision_anchor":"coordination.price_signal","graph_fact_supports":[[{"evidence_id":"v141-b-g13-E13","quote":"Step 3, the aggregators will send back the tentative demand responses (DRs) to the DSO. Step 4, with the new information, the DSO will be able to identify the congestion points (if any) and modify the DPT rates according to the identified congestion."}],[{"evidence_id":"v141-b-g12-E12","quote":"An important task in the implementation of the DPT method for congestion management is to determine a proper DPT rate for each node (load bus) and each time period according to the network conditions and forecasted nonflexible load level, so that the energy schedules of the aggregators respect the network limits."}],[{"evidence_id":"v141-b-g13-E13","quote":"Step 1, the DSO initiates the iterative process by sending out tentative DPTs (= 0)."}],[{"evidence_id":"v141-b-g13-E13","quote":"Step 5, the DSO sends out the new DPTs to the aggregator and the iterative process continues (go back to Step 2) till the network constraints are satisfied and the final DPT rates are determined."}],[{"evidence_id":"v141-b-g02-e016","quote":"Afterwards, two limiters force the signals to be nonnegative, which are corresponding to (14) and (15), respectively. Then the signals (marginal prices for line flow and voltage respectively) are transformed to DPTs"}],[{"evidence_id":"v141-b-g02-e013","quote":"When the iteration converges, the residuals in (11) and (12) will be nonpositive, which means constraints (7) and (8) are satisfied."},{"evidence_id":"v141-b-g02-e013","quote":"The final DPT rates are the same as the last iteration DPT rates (Fig. 2)."}]],"C2_formalization":{"graph_sha256":"ba6a3631c8bc8c01b700d35b311466a38f780afde006976440286584128510de","applicability":"formalized","reason":"The frozen graph supports a high-level price-signal coordination rule: demand-response information in bidding.demand feeds DPT coordination signals in coordination.price_signal via edge v141-c-R003-E001. The source provides explicit iterative DPT update equations (11)-(13), nonnegativity limiters (14)-(15), initialization, and convergence conditions. I formalize those source formulas and retain the original procedural constraints. B evidence remains unreviewed under this experiment; this formalization is provisional and does not assert independent source review.","bindings":[{"object_id":"v141-c-R003-X001","node_ids":["coordination.price_signal"],"edge_ids":[],"rationale":"lambda_t is an internal line-flow marginal-price signal used to form the DPT coordination signal in coordination.price_signal."},{"object_id":"v141-c-R003-X002","node_ids":["coordination.price_signal"],"edge_ids":[],"rationale":"omega_t is an internal voltage marginal-price signal used to form the DPT coordination signal in coordination.price_signal."},{"object_id":"v141-c-R003-X003","node_ids":["coordination.price_signal"],"edge_ids":["v141-c-R003-E001"],"rationale":"R_t is the matrix form of the DPT rates, the coordination output whose update is informed by demand-response information through the demand-to-price-signal edge."},{"object_id":"v141-c-R003-X004","node_ids":["bidding.demand"],"edge_ids":["v141-c-R003-E001"],"rationale":"s_t is the apparent-power load assembled from aggregator demand responses and conventional load; it enters the DPT update through the demand-to-price-signal edge."},{"object_id":"v141-c-R003-P001","node_ids":["coordination.price_signal"],"edge_ids":[],"rationale":"alpha is the step size in the update of the coordination signals."},{"object_id":"v141-c-R003-P002","node_ids":["coordination.price_signal"],"edge_ids":[],"rationale":"tau is the convergence tolerance applied to the coordination-signal updates."},{"object_id":"v141-c-R003-P003","node_ids":["coordination.price_signal"],"edge_ids":[],"rationale":"D is the PTDF matrix used in the line-flow residual and DPT transformation."},{"object_id":"v141-c-R003-P004","node_ids":["coordination.price_signal"],"edge_ids":[],"rationale":"F_t is the line-flow limit entering the DPT residual update."},{"object_id":"v141-c-R003-P005","node_ids":["coordination.price_signal"],"edge_ids":[],"rationale":"Z is the network admittance-derived matrix entering the voltage residual and voltage-signal transformation."},{"object_id":"v141-c-R003-P006","node_ids":["coordination.price_signal"],"edge_ids":[],"rationale":"V_0 is the node-0 voltage normalizing the voltage residual and transformation."},{"object_id":"v141-c-R003-P007","node_ids":["coordination.price_signal"],"edge_ids":[],"rationale":"The lower voltage limit enters the voltage residual of the DPT update."},{"object_id":"v141-c-R003-C003","node_ids":["coordination.price_signal"],"edge_ids":[],"rationale":"Initialization sets the DPT coordination signals and marginal-price signals to zero before iteration."},{"object_id":"v141-c-R003-C004","node_ids":["coordination.price_signal"],"edge_ids":["v141-c-R003-E001"],"rationale":"Convergence is tested on the residual/updates of the coordination signals generated from demand-response information."},{"object_id":"v141-c-R003-C005","node_ids":["coordination.price_signal"],"edge_ids":[],"rationale":"Nonnegativity applies to the internal marginal-price signals in coordination.price_signal before DPT transformation."},{"object_id":"v141-c-R003-C006","node_ids":["coordination.price_signal"],"edge_ids":[],"rationale":"Finalization fixes the DPT rate output to the last-iteration value in coordination.price_signal."},{"object_id":"v141-c-R003-C007","node_ids":["bidding.demand","coordination.price_signal"],"edge_ids":["v141-c-R003-E001"],"rationale":"The update equations consume demand-response-derived network load s_t and produce updated DPT coordination signals, exactly along the demand-to-price-signal edge."}],"revision_requests":[]}},"quarantined_references":[]}});
